using System.Collections.Generic; using System.Linq; using UnityEngine; namespace MyLumo { public class WorldRegistry:MonoBehaviour { public static WorldRegistry Instance{get;private set;} WorldAnchor[] anchors; void Awake(){Instance=this;Refresh();} public void Refresh()=>anchors=FindObjectsByType<WorldAnchor>(FindObjectsSortMode.None); public WorldAnchor FindFor(LumoLocation l,LumoActionType a,string target=""){if(anchors==null||anchors.Length==0)Refresh();IEnumerable<WorldAnchor> q=anchors.Where(x=>x.location==l);if(a!=LumoActionType.Move){var e=q.FirstOrDefault(x=>x.supportedAction==a&&(string.IsNullOrWhiteSpace(target)||x.anchorId==target));if(e)return e;}return q.FirstOrDefault(x=>x.supportedAction==LumoActionType.Move)??q.FirstOrDefault();} } }
